"""Bounded integer event import API, current implementation."""
import copy
import re


def new_state():
    return {"events": {}, "totals": {}}


def _event(value, path):
    if type(value) is not dict or set(value) != {"id", "revision", "account", "amount"}:
        raise ValueError(path + ":event_shape")
    for field in ("id", "account"):
        if type(value[field]) is not str or not re.fullmatch(r"[A-Za-z][A-Za-z0-9_]{0,15}", value[field]):
            raise ValueError(path + "." + field + ":invalid_name")
    if type(value["revision"]) is not int or not 0 <= value["revision"] <= 1000:
        raise ValueError(path + ".revision:integer_range")
    if type(value["amount"]) is not int or not -1000 <= value["amount"] <= 1000:
        raise ValueError(path + ".amount:integer_range")


def apply_batch(state, batch):
    if type(batch) is not list or len(batch) > 8:
        raise ValueError("batch:invalid_size")

    # Validate all events first (shape/type)
    for index, event in enumerate(batch):
        path = "batch[" + str(index) + "]"
        _event(event, path)

    # Check capacity - we can only have <= 8 unique event IDs in the store
    unique_ids = set()
    for event in batch:
        if event["id"] in unique_ids:
            raise ValueError("batch:store_capacity")
        unique_ids.add(event["id"])
    if len(unique_ids) > 8:
        raise ValueError("batch:store_capacity")

    # Check for conflicts BEFORE any state changes
    for index, event in enumerate(batch):
        path = "batch[" + str(index) + "]"
        eid = event["id"]
        old = state["events"].get(eid)

        if old is not None:
            # Same revision but different content = conflict
            if event["revision"] == old["revision"] and event != old:
                raise ValueError(path + ":revision_conflict")
            # Lower revision = ignored (no error, just skip)
            # Higher revision = replace (no error, no delta, just replace)

    # Now apply changes atomically
    # For each event:
    # - New event: add full amount, store event
    # - Higher revision: replace amount (delta = new - old), store new event
    # - Same revision: should be caught by conflict check
    # - Lower revision: skip (no change)

    # Calculate changes
    changes = {}  # eid -> amount to add to totals
    new_events = {}  # eid -> new event dict

    for event in batch:
        eid = event["id"]
        old = state["events"].get(eid)

        if old is None:
            # New event
            changes[eid] = event["amount"]
            new_events[eid] = event
        elif event["revision"] > old["revision"]:
            # Higher revision: replace the contribution
            changes[eid] = event["amount"] - old["amount"]
            new_events[eid] = event
        else:
            # Lower or same revision: skip (lower is ignored, same is conflict)
            continue

    # Apply changes to totals
    for eid, delta in changes.items():
        account = new_events[eid]["account"]
        state["totals"][account] = state["totals"].get(account, 0) + delta

    # Update events
    for eid, event in new_events.items():
        state["events"][eid] = copy.deepcopy(event)


def snapshot(state):
    # Sort events by id for deterministic output
    sorted_events = [state["events"][key] for key in sorted(state["events"])]
    return {"events": sorted_events, "totals": dict(sorted(state["totals"].items()))}


def restore(state, checkpoint):
    """Restore state from a checkpoint. The checkpoint must be a valid snapshot."""
    if type(checkpoint) is not dict:
        raise ValueError("checkpoint:invalid")
    if set(checkpoint) != {"events", "totals"}:
        raise ValueError("checkpoint:invalid")
    if type(checkpoint["events"]) is not list:
        raise ValueError("checkpoint:invalid")
    if type(checkpoint["totals"]) is not dict:
        raise ValueError("checkpoint:invalid")

    # Validate checkpoint format and event bounds
    for event in checkpoint["events"]:
        _event(event, "checkpoint.events")

    # Check uniqueness
    unique_ids = set()
    for event in checkpoint["events"]:
        if event["id"] in unique_ids:
            raise ValueError("checkpoint:invalid")
        unique_ids.add(event["id"])
    if len(unique_ids) > 8:
        raise ValueError("checkpoint:invalid")

    # Restore state exactly
    state["events"] = {e["id"]: copy.deepcopy(e) for e in checkpoint["events"]}
    state["totals"] = dict(sorted(checkpoint["totals"].items()))


def replay(batches, checkpoint=None):
    """Replay batches from a checkpoint (or empty state)."""
    if checkpoint is None:
        state = new_state()
    else:
        state = new_state()
        restore(state, checkpoint)

    if type(batches) is not list:
        raise ValueError("batches:invalid_size")

    for batch in batches:
        apply_batch(state, batch)

    return snapshot(state)

"""Immutable event store with atomic batch application."""

def new_state():
    return {"events": {}, "totals": {}}

def apply_batch(state, batch):
    """
    Apply a batch of events atomically. Returns None on success.
    Raises ValueError with appropriate message on failure.

    Atomicity: No state changes occur unless ALL validations pass.
    - Idempotent replay: Same event id+revision is a no-op
    - Conflict: Same event id with same revision but different content -> reject entire batch
    - Higher revision: Replace old event (remove old contribution, add new)
    """
    # Validate batch is a list
    if type(batch) is not list:
        raise ValueError("batch:invalid_size")
    if len(batch) > 8:
        raise ValueError("batch:invalid_size")

    # First pass: validate all events and check for conflicts WITHOUT modifying state
    validated = []
    for event in batch:
        # Validate shape
        if not isinstance(event, dict):
            raise ValueError("batch[i]:event_shape")

        # Check required keys
        for key in ["id", "revision", "account", "amount"]:
            if key not in event:
                raise ValueError("batch[i]:event_shape")

        # Validate id
        if not isinstance(event["id"], str) or not event["id"] or not event["id"][0].isalpha():
            if not event["id"]:
                raise ValueError("batch[i]:id:invalid_name")
            if not event["id"][0].isalpha():
                raise ValueError("batch[i]:id:invalid_name")
            if not all(c.isalnum() or c == "_" for c in event["id"]):
                raise ValueError("batch[i]:id:invalid_name")
            if len(event["id"]) > 16:
                raise ValueError("batch[i]:id:invalid_name")

        # Validate account
        if not isinstance(event["account"], str) or not event["account"] or not event["account"][0].isalpha():
            if not event["account"]:
                raise ValueError("batch[i]:account:invalid_name")
            if not event["account"][0].isalpha():
                raise ValueError("batch[i]:account:invalid_name")
            if not all(c.isalnum() or c == "_" for c in event["account"]):
                raise ValueError("batch[i]:account:invalid_name")
            if len(event["account"]) > 16:
                raise ValueError("batch[i]:account:invalid_name")

        # Validate revision
        if not isinstance(event["revision"], int) or event["revision"] < 0 or event["revision"] > 1000:
            raise ValueError("batch[i]:revision:integer_range")

        # Validate amount
        if not isinstance(event["amount"], int) or event["amount"] < -1000 or event["amount"] > 1000:
            raise ValueError("batch[i]:amount:integer_range")

        # Check for conflicts (same id, same revision, but different content)
        existing = state["events"].get(event["id"])
        if existing is not None:
            if existing["revision"] == event["revision"]:
                # Same revision but different content - conflict
                raise ValueError("batch[i]:revision_conflict")
            # If revision is higher, we'll handle it in apply phase (remove old, add new)

        validated.append(event)

    # Check store capacity
    if len(validated) + len(state["events"]) > 8:
        raise ValueError("batch:store_capacity")

    # Now apply changes atomically
    # First, remove old contributions that will be replaced
    for event in validated:
        eid = event["id"]
        existing = state["events"].get(eid)
        if existing is not None:
            old_account = existing["account"]
            old_amount = existing["amount"]
            # Remove old contribution from totals
            state["totals"][old_account] = state["totals"].get(old_account, 0) - old_amount
            # Remove the old event
            del state["events"][eid]

    # Add new events
    for event in validated:
        eid = event["id"]
        state["events"][eid] = {
            "id": event["id"],
            "revision": event["revision"],
            "account": event["account"],
            "amount": event["amount"]
        }

    # Update totals with new contributions
    for event in validated:
        account = event["account"]
        amount = event["amount"]
        state["totals"][account] = state["totals"].get(account, 0) + amount

    return None

def snapshot(state):
    """Return a deep copy of the state with events sorted by id."""
    sorted_events = []
    for eid in sorted(state["events"].keys()):
        event = state["events"][eid]
        sorted_events.append({
            "id": event["id"],
            "revision": event["revision"],
            "account": event["account"],
            "amount": event["amount"]
        })
    # Deep copy totals
    total_copy = dict(state["totals"])
    return {"events": sorted_events, "totals": total_copy}

"""Bounded integer event import API, current implementation."""
import copy
import re


def new_state():
    return {"events": {}, "totals": {}}


def _event(value, path):
    if type(value) is not dict or set(value) != {"id", "revision", "account", "amount"}:
        raise ValueError(path + ":event_shape")
    for field in ("id", "account"):
        if type(value[field]) is not str or not re.fullmatch(r"[A-Za-z][A-Za-z0-9_]{0,15}", value[field]):
            raise ValueError(path + "." + field + ":invalid_name")
    if type(value["revision"]) is not int or not 0 <= value["revision"] <= 1000:
        raise ValueError(path + ".revision:integer_range")
    if type(value["amount"]) is not int or not -1000 <= value["amount"] <= 1000:
        raise ValueError(path + ".amount:integer_range")


def _conflict_path(index, batch):
    return "batch[" + str(index) + "]:revision_conflict"


def apply_batch(state, batch):
    """Apply a batch atomically - all or nothing. Returns (ok, state, error)."""
    if type(batch) is not list or len(batch) > 8:
        raise ValueError("batch:invalid_size")

    # Phase 1: Validate all events
    validated = []
    for index, event in enumerate(batch):
        path = "batch[" + str(index) + "]"
        _event(event, path)
        validated.append((index, event))

    # Check store capacity (max 8 unique event IDs)
    new_ids = set(event["id"] for index, event in validated)
    current_ids = set(state["events"].keys())
    all_ids = current_ids | new_ids
    if len(all_ids) > 8:
        raise ValueError(batch[0]["id"] if batch else "batch:store_capacity")

    # Phase 2: Check for conflicts BEFORE applying any changes
    # Build a map of old events by ID
    old_events = {eid: ev for eid, ev in state["events"].items()}

    for index, event in validated:
        old = old_events.get(event["id"])
        if old is not None:
            # Stale revision (lower) - reject entire batch
            if event["revision"] < old["revision"]:
                raise _conflict_path(index, batch)
            # Same revision but different content - conflict
            if event["revision"] == old["revision"] and event != old:
                raise _conflict_path(index, batch)
            # Higher revision or exact replay - no conflict

    # Phase 3: Apply all changes atomically
    # Calculate what the new state should be
    new_events = {}
    for index, event in validated:
        event_id = event["id"]
        old = old_events.get(event_id)
        if old is None:
            # New event
            new_events[event_id] = copy.deepcopy(event)
        elif event == old:
            # Exact replay - no change
            new_events[event_id] = old
        else:
            # Higher revision - replace with copy
            new_events[event_id] = copy.deepcopy(event)

    # Calculate new totals
    new_totals = {}
    for event_id, event in new_events.items():
        account = event["account"]
        amount = event["amount"]
        new_totals[account] = new_totals.get(account, 0) + amount

    # Apply the new state
    state["events"] = new_events
    state["totals"] = new_totals

    return (True, state, None)


def snapshot(state):
    """Return a deep copy of the state."""
    return {
        "events": [copy.deepcopy(ev) for ev in sorted(state["events"].values(), key=lambda e: e["id"])],
        "totals": dict(state["totals"])
    }


def restore(state, checkpoint):
    """Restore state from a checkpoint."""
    if type(checkpoint) is not dict:
        raise ValueError("checkpoint:invalid")
    if set(checkpoint) != {"events", "totals"}:
        raise ValueError("checkpoint:invalid")
    if type(checkpoint["events"]) is not list:
        raise ValueError("checkpoint:invalid")
    if type(checkpoint["totals"]) is not dict:
        raise ValueError("checkpoint:invalid")

    # Validate events
    seen_ids = set()
    for ev in checkpoint["events"]:
        if type(ev) is not dict or set(ev) != {"id", "revision", "account", "amount"}:
            raise ValueError("checkpoint:invalid")
        # Validate bounds
        for field in ("id", "account"):
            if type(ev[field]) is not str or not re.fullmatch(r"[A-Za-z][A-Za-z0-9_]{0,15}", ev[field]):
                raise ValueError("checkpoint:invalid")
        if type(ev["revision"]) is not int or not 0 <= ev["revision"] <= 1000:
            raise ValueError("checkpoint:invalid")
        if type(ev["amount"]) is not int or not -1000 <= ev["amount"] <= 1000:
            raise ValueError("checkpoint:invalid")
        if ev["id"] in seen_ids:
            raise ValueError("checkpoint:invalid")
        seen_ids.add(ev["id"])

    if len(seen_ids) > 8:
        raise ValueError("checkpoint:invalid")

    # Validate totals
    for account, total in checkpoint["totals"].items():
        if type(account) is not str or not re.fullmatch(r"[A-Za-z][A-Za-z0-9_]{0,15}", account):
            raise ValueError("checkpoint:invalid")
        if type(total) is not int:
            raise ValueError("checkpoint:invalid")

    # Restore state
    state["events"] = {ev["id"]: copy.deepcopy(ev) for ev in checkpoint["events"]}
    state["totals"] = dict(checkpoint["totals"])

    return (True, state, None)


def replay(state, batches, checkpoint=None):
    """Replay batches starting from checkpoint or empty state."""
    if checkpoint is not None:
        restore(state, checkpoint)

    if type(batches) is not list:
        raise ValueError("batches:invalid_size")

    for batch in batches:
        ok, state, err = apply_batch(state, batch)
        if not ok:
            raise ValueError(err)

    return (True, state, None)
